content.content:
  1→//! Dual-write compatibility layer (P1-W4).
  2→//!
  3→//! Provides V1 → V2 conversion functions and orchestration so every wallet
  4→//! ingestion writes both V1 tables (`transactions`, `indexer_checkpoints`) and
  5→//! V2 tables (`raw_transactions`, `target_matches`, `checkpoints`).
  6→//!
  7→//! V2 writes are best-effort: failures are logged but never abort the V1 path.
  8→
  9→use chrono::Utc;
 10→use spectraplex_core::models::{Chain, IndexerCheckpoint, Transaction};
 11→use spectraplex_core::v2::{
 12→    ChainFamily, Checkpoint, IndexTarget, RawTransaction, TargetKind, TargetMatch, TargetMode,
 13→};
 14→use tracing::{info, warn};
 15→use uuid::Uuid;
 16→
 17→use crate::repo::Repository;
 18→
 19→// ---------------------------------------------------------------------------
 20→// Chain → Network / Source mapping  (Rollout Plan Section 2.4)
 21→// ---------------------------------------------------------------------------
 22→
 23→/// Map a V1 `Chain` to the default V2 network identifier.
 24→///
 25→/// Matches Rollout Plan Section 2.4 exactly:
 26→/// - `Solana`       → `"solana-mainnet"`
 27→/// - `Ethereum`     → `"ethereum-mainnet"`
 28→/// - `Hyperliquid`  → `"hypercore-mainnet"`
 29→pub fn chain_to_default_network(chain: &Chain) -> &'static str {
 30→    match chain {
 31→        Chain::Solana => "solana-mainnet",
 32→        Chain::Ethereum => "ethereum-mainnet",
 33→        Chain::Hyperliquid => "hypercore-mainnet",
 34→    }
 35→}
 36→
 37→/// Map a V1 `Chain` to the default V2 ingestion source.
 38→///
 39→/// Matches Rollout Plan Section 2.4 exactly:
 40→/// - `Solana`       → `"rpc"`
 41→/// - `Ethereum`     → `"rpc"`
 42→/// - `Hyperliquid`  → `"rest"`
 43→pub fn chain_to_default_source(chain: &Chain) -> &'static str {
 44→    match chain {
 45→        Chain::Solana => "rpc",
 46→        Chain::Ethereum => "rpc",
 47→        Chain::Hyperliquid => "rest",
 48→    }
 49→}
 50→
 51→// ---------------------------------------------------------------------------
 52→// V1 → V2 conversion functions
 53→// ---------------------------------------------------------------------------
 54→
 55→/// Convert a V1 `Transaction` to a V2 `RawTransaction`.
 56→///
 57→/// Per Rollout Plan Section 2.2:
 58→/// - `user_id` and `wallet_address` are stripped (target-agnostic)
 59→/// - `chain` maps to `network` via `chain_to_default_network`
 60→/// - `source` maps via `chain_to_default_source`
 61→/// - `block_number` is extracted from `raw_metadata` (Solana: `slot`, EVM: `block_number`)
 62→/// - `id`, `timestamp`, `tx_hash`, `raw_metadata` are copied directly
 63→pub fn v1_tx_to_v2_raw(tx: &Transaction) -> RawTransaction {
 64→    let block_number = extract_block_number(&tx.chain, &tx.raw_metadata);
 65→
 66→    RawTransaction {
 67→        id: tx.id,
 68→        network: chain_to_default_network(&tx.chain).to_string(),
 69→        tx_hash: tx.tx_hash.clone(),
 70→        timestamp: tx.timestamp,
 71→        block_number,
 72→        raw_metadata: tx.raw_metadata.clone(),
 73→        source: chain_to_default_source(&tx.chain).to_string(),
 74→        ingestion_run_id: None,
 75→        ingested_at: Utc::now(),
 76→    }
 77→}
 78→
 79→/// Extract `block_number` from raw_metadata based on chain.
 80→///
 81→/// - Solana: `raw_metadata["slot"]`
 82→/// - Ethereum: `raw_metadata["block_number"]`
 83→/// - Hyperliquid: None (blockless chain)
 84→fn extract_block_number(chain: &Chain, metadata: &serde_json::Value) -> Option<i64> {
 85→    match chain {
 86→        Chain::Solana => metadata.get("slot").and_then(|v| v.as_i64()),
 87→        Chain::Ethereum => metadata.get("block_number").and_then(|v| v.as_i64()),
 88→        Chain::Hyperliquid => None,
 89→    }
 90→}
 91→
 92→/// Convert a V1 `IndexerCheckpoint` to a V2 `Checkpoint`.
 93→///
 94→/// Per P0-W3 Section 5 / Rollout Plan Section 2.3:
 95→/// - Builds a JSONB cursor from the flat V1 fields
 96→/// - Solana cursor: `{ last_signature, last_slot }`
 97→/// - EVM cursor: `{ last_block }`
 98→/// - HyperCore cursor: `{ last_timestamp_ms }` (seconds * 1000)
 99→pub fn v1_checkpoint_to_v2(cp: &IndexerCheckpoint, target_id: Uuid) -> Checkpoint {
100→    let network = chain_to_default_network(&cp.chain).to_string();
101→    let source = chain_to_default_source(&cp.chain).to_string();
102→
103→    let cursor = build_v2_cursor(cp);
104→
105→    Checkpoint {
106→        id: Uuid::new_v4(),
107→        target_id,
108→        network,
109→        source,
110→        cursor,
111→        updated_at: Utc::now(),
112→    }
113→}
114→
115→/// Build the JSONB cursor from V1 checkpoint fields.
116→///
117→/// Per P0-W3 Sections 5.2–5.5 and Section 9.4:
118→/// - Solana: `{ "last_signature": ..., "last_slot": ... }`
119→/// - EVM: `{ "last_block": ... }`
120→/// - HyperCore: `{ "last_timestamp_ms": ... }` (seconds * 1000)
121→///
122→/// Only non-None fields are included.
123→fn build_v2_cursor(cp: &IndexerCheckpoint) -> serde_json::Value {
124→    let mut cursor = serde_json::Map::new();
125→
126→    match cp.chain {
127→        Chain::Solana => {
128→            if let Some(ref sig) = cp.last_signature {
129→                cursor.insert(
130→                    "last_signature".to_string(),
131→                    serde_json::Value::String(sig.clone()),
132→                );
133→            }
134→            if let Some(slot) = cp.last_slot {
135→                cursor.insert(
136→                    "last_slot".to_string(),
137→                    serde_json::Value::Number(serde_json::Number::from(slot)),
138→                );
139→            }
140→        }
141→        Chain::Ethereum => {
142→            if let Some(block) = cp.last_block {
143→                cursor.insert(
144→                    "last_block".to_string(),
145→                    serde_json::Value::Number(serde_json::Number::from(block)),
146→                );
147→            }
148→        }
149→        Chain::Hyperliquid => {
150→            if let Some(ts) = cp.last_timestamp {
151→                let ts_ms = ts * 1000;
152→                cursor.insert(
153→                    "last_timestamp_ms".to_string(),
154→                    serde_json::Value::Number(serde_json::Number::from(ts_ms)),
155→                );
156→            }
157→        }
158→    }
159→
160→    serde_json::Value::Object(cursor)
161→}
162→
163→/// Build `TargetMatch` rows linking a target to a set of raw transaction IDs.
164→///
165→/// All matches use `match_reason = "sender"` since V1 wallet ingestion finds
166→/// transactions where the wallet is the sender/signer.
167→pub fn build_target_matches(target_id: Uuid, raw_tx_ids: &[Uuid]) -> Vec<TargetMatch> {
168→    let now = Utc::now();
169→    raw_tx_ids
170→        .iter()
171→        .map(|&raw_tx_id| TargetMatch {
172→            id: Uuid::new_v4(),
173→            target_id,
174→            raw_transaction_id: raw_tx_id,
175→            match_reason: Some("sender".to_string()),
176→            matched_at: now,
177→        })
178→        .collect()
179→}
180→
181→// ---------------------------------------------------------------------------
182→// ensure_wallet_target: idempotent wallet target creation
183→// ---------------------------------------------------------------------------
184→
185→impl Repository {
186→    /// Look up or create an `IndexTarget` for the given wallet address.
187→    ///
188→    /// Idempotent: if a target with `(kind=Wallet, network, address)` already
189→    /// exists, it is returned. Otherwise a new one is created with
190→    /// `mode=Both` and `chain_family` derived from the chain.
191→    pub async fn ensure_wallet_target(
192→        &self,
193→        chain: &Chain,
194→        wallet_address: &str,
195→        owner_id: Option<Uuid>,
196→    ) -> anyhow::Result<IndexTarget> {
197→        let network = chain_to_default_network(chain);
198→        let chain_family = ChainFamily::from(chain.clone());
199→
200→        // Check if target already exists
201→        if let Some(existing) = self
202→            .get_index_target_by_address(TargetKind::Wallet, network, wallet_address)
203→            .await?
204→        {
205→            return Ok(existing);
206→        }
207→
208→        // Create new target
209→        let now = Utc::now();
210→        let target = IndexTarget {
211→            id: Uuid::new_v4(),
212→            kind: TargetKind::Wallet,
213→            network: network.to_string(),
214→            chain_family,
215→            address: Some(wallet_address.to_string()),
216→            filter_spec: None,
217→            mode: TargetMode::Both,
218→            label: None,
219→            owner_id,
220→            created_at: now,
221→            updated_at: now,
222→        };
223→
224→        self.create_index_target(&target).await?;
225→        info!(
226→            target_id = %target.id,
227→            wallet = %wallet_address,
228→            network = %network,
229→            "Created wallet IndexTarget via compatibility shim"
230→        );
231→        Ok(target)
232→    }
233→
234→    // -----------------------------------------------------------------------
235→    // Dual-write orchestration
236→    // -----------------------------------------------------------------------
237→
238→    /// Save transactions using both V1 and V2 paths.
239→    ///
240→    /// V1 write (`save_transactions`) executes first. V2 writes
241→    /// (`save_raw_transactions` + `save_target_matches`) are best-effort:
242→    /// failures are logged but do not fail the operation.
243→    pub async fn save_transactions_dual_write(
244→        &self,
245→        txs: &[Transaction],
246→        target_id: Uuid,
247→    ) -> anyhow::Result<()> {
248→        // V1 write (authoritative)
249→        self.save_transactions(txs).await?;
250→
251→        // V2 write (best-effort)
252→        if let Err(e) = self.v2_write_transactions(txs, target_id).await {
253→            warn!(
254→                error = %e,
255→                target_id = %target_id,
256→                count = txs.len(),
257→                "V2 dual-write for transactions failed (V1 write succeeded)"
258→            );
259→        }
260→
261→        Ok(())
262→    }
263→
264→    /// Save a checkpoint using both V1 and V2 paths.
265→    ///
266→    /// V1 write (`save_checkpoint`) executes first. V2 write
267→    /// (`upsert_checkpoint_v2`) is best-effort.
268→    pub async fn save_checkpoint_dual_write(
269→        &self,
270→        checkpoint: &IndexerCheckpoint,
271→        target_id: Uuid,
272→    ) -> anyhow::Result<()> {
273→        // V1 write (authoritative)
274→        self.save_checkpoint(checkpoint).await?;
275→
276→        // V2 write (best-effort)
277→        let v2_cp = v1_checkpoint_to_v2(checkpoint, target_id);
278→        if let Err(e) = self.upsert_checkpoint_v2(&v2_cp).await {
279→            warn!(
280→                error = %e,
281→                target_id = %target_id,
282→                "V2 dual-write for checkpoint failed (V1 write succeeded)"
283→            );
284→        }
285→
286→        Ok(())
287→    }
288→
289→    /// Combined dual-write for transactions and checkpoint.
290→    ///
291→    /// V1 path uses `save_transactions_and_checkpoint` (atomic). V2 writes
292→    /// are best-effort and run after V1 succeeds.
293→    pub async fn save_transactions_and_checkpoint_dual_write(
294→        &self,
295→        txs: &[Transaction],
296→        checkpoint: &IndexerCheckpoint,
297→        target_id: Uuid,
298→    ) -> anyhow::Result<()> {
299→        // V1 write (authoritative, atomic)
300→        self.save_transactions_and_checkpoint(txs, checkpoint)
301→            .await?;
302→
303→        // V2 write (best-effort)
304→        if let Err(e) = self.v2_write_transactions(txs, target_id).await {
305→            warn!(
306→                error = %e,
307→                target_id = %target_id,
308→                count = txs.len(),
309→                "V2 dual-write for transactions failed (V1 write succeeded)"
310→            );
311→        }
312→
313→        let v2_cp = v1_checkpoint_to_v2(checkpoint, target_id);
314→        if let Err(e) = self.upsert_checkpoint_v2(&v2_cp).await {
315→            warn!(
316→                error = %e,
317→                target_id = %target_id,
318→                "V2 dual-write for checkpoint failed (V1 write succeeded)"
319→            );
320→        }
321→
322→        Ok(())
323→    }
324→
325→    /// Internal: convert and write V2 raw_transactions + target_matches.
326→    async fn v2_write_transactions(
327→        &self,
328→        txs: &[Transaction],
329→        target_id: Uuid,
330→    ) -> anyhow::Result<()> {
331→        if txs.is_empty() {
332→            return Ok(());
333→        }
334→
335→        let v2_txs: Vec<RawTransaction> = txs.iter().map(v1_tx_to_v2_raw).collect();
336→        self.save_raw_transactions(&v2_txs).await?;
337→
338→        let raw_tx_ids: Vec<Uuid> = v2_txs.iter().map(|rt| rt.id).collect();
339→        let matches = build_target_matches(target_id, &raw_tx_ids);
340→        self.save_target_matches(&matches).await?;
341→
342→        Ok(())
343→    }
344→}
